practice.solution:
const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");
const n = Number(lines[0]);

class Student {
  constructor(name, scores) {
    this.name = name;
    this.scores = scores;
  }

  average() {
    return this.scores.reduce((sum, s) => sum + s, 0) / this.scores.length;
  }
}

const students = lines.slice(1, n + 1).map((line) => {
  const [name, ...scores] = line.trim().split(/\s+/);
  return new Student(name, scores.map(Number));
});

students.sort((a, b) =>
  Math.round(b.average() * 10) - Math.round(a.average() * 10) || a.name.localeCompare(b.name)
);

for (const student of students) {
  console.log(`${student.name}: ${student.average().toFixed(1)}`);
}
